// Un cliente le pide a un servidor «reservar un camión». La red pierde mensajes con una probabilidad p en cada sentido.
function azar(semilla) { let a = semilla; return () => { a |= 0; a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }

function intento(r, p) {
  const pedidoLlega = r() >= p;            // ¿llegó el pedido al servidor?
  const ejecutado = pedidoLlega;           // si llega, el servidor reserva
  const respuestaLlega = ejecutado && r() >= p;
  return { ejecutado, confirmado: respuestaLlega }; // el cliente solo ve «confirmado» o silencio (timeout)
}

const r = azar(2026), p = 0.10, N = 100_000;
const c = { confirmado: 0, silencio_noEjecutado: 0, silencio_SIejecutado: 0 };
for (let i = 0; i < N; i++) {
  const { ejecutado, confirmado } = intento(r, p);
  if (confirmado) c.confirmado++;
  else if (ejecutado) c.silencio_SIejecutado++;
  else c.silencio_noEjecutado++;
}
console.log('p de pérdida por sentido =', p, '· intentos =', N);
for (const [k, v] of Object.entries(c)) console.log(k.padEnd(24), String(v).padStart(7), (100 * v / N).toFixed(1) + ' %');
const silencios = c.silencio_noEjecutado + c.silencio_SIejecutado;
console.log('de los silencios, el servidor SÍ había reservado:', (100 * c.silencio_SIejecutado / silencios).toFixed(1) + ' %');

// Política ingenua: ante el silencio, reintentar hasta 3 veces. ¿Cuántos camiones se reservan de más?
let reservas = 0, clientesConfirmados = 0, M = 100_000;
for (let i = 0; i < M; i++) {
  let ok = false;
  for (let k = 0; k < 3 && !ok; k++) { const x = intento(r, p); if (x.ejecutado) reservas++; ok = x.confirmado; }
  if (ok) clientesConfirmados++;
}
console.log('reintento ingenuo: reservas hechas =', reservas, 'para', M, 'clientes →', ((reservas / M - 1) * 100).toFixed(1) + ' % de reservas de más');

// Tres nodos con copia del stock de un producto (10 unidades). Se corta el enlace: {Norte1, Norte2} quedan separados de {Sur}.
function simular(politica) {
  const nodos = { Norte1: { stock: 10 }, Norte2: { stock: 10 }, Sur: { stock: 10 } };
  const lado = { Norte1: 'A', Norte2: 'A', Sur: 'B' };
  const tamLado = { A: 2, B: 1 }, total = 3;
  const pedidos = [['Norte1', 4], ['Sur', 3], ['Norte2', 3], ['Sur', 3]];   // [nodo que recibe, unidades]
  const acepta = (nodo) => politica === 'siempre' || tamLado[lado[nodo]] > total / 2;
  let aceptados = 0, rechazados = 0;
  for (const [n, u] of pedidos) {
    if (acepta(n)) { nodos[n].stock -= u; aceptados += u; }
    else rechazados += u;
  }
  // el enlace vuelve: cada lado le cuenta al otro lo que vendió (se suman las ventas; ya no hay forma de deshacerlas)
  const vendido = Object.values(nodos).reduce((s, n) => s + (10 - n.stock), 0); // lo vendido en cada nodo, sumado
  const stockFinal = 10 - vendido;
  console.log(politica.padEnd(8), '· aceptadas', aceptados, '· rechazadas', rechazados, '· stock al sanar =', stockFinal, stockFinal < 0 ? '→ vendiste ' + (-stockFinal) + ' unidades que no tenías' : '');
}
simular('siempre');
simular('mayoria');

// Dos generales: cadena de k mensajes con confirmaciones. Cada mensaje se pierde con probabilidad p y solo se manda el siguiente si el anterior llegó.
function azar(semilla) { let a = semilla; return () => { a |= 0; a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const r = azar(11), p = 0.2, N = 200_000;
console.log('k mensajes   cadena completa   último perdido, dado que llegaron los k-1 anteriores');
for (const k of [1, 2, 3, 5, 8]) {
  let completa = 0, previosOk = 0, ultimoPerdido = 0;
  for (let i = 0; i < N; i++) {
    let llegaron = 0;
    for (let m = 1; m <= k; m++) { if (r() < p) break; llegaron++; }
    if (llegaron === k) completa++;
    if (llegaron >= k - 1) { previosOk++; if (llegaron === k - 1) ultimoPerdido++; }
  }
  console.log(String(k).padStart(9), (100 * completa / N).toFixed(1).padStart(14) + ' %', (100 * ultimoPerdido / previosOk).toFixed(1).padStart(30) + ' %');
}
